mapper.select:
SELECT ID AS id, name, dept_name, tot_cred
FROM student
WHERE ID = #{id}

SELECT s.course_id, s.sec_id, s.semester, s.year, s.building, s.room_number, s.time_slot_id, c.title AS course_title, c.credits, (SELECT GROUP_CONCAT(i.name SEPARATOR '、') FROM teaches t JOIN instructor i ON t.ID = i.ID WHERE t.course_id = s.course_id AND t.sec_id = s.sec_id AND t.semester = s.semester AND t.year = s.year) AS instructor_names, (SELECT COUNT(*) FROM takes k WHERE k.course_id = s.course_id AND k.sec_id = s.sec_id AND k.semester = s.semester AND k.year = s.year) AS enrolled, cl.capacity, CASE WHEN myt.ID IS NOT NULL THEN 1 ELSE 0 END AS selected FROM section s JOIN course c ON s.course_id = c.course_id LEFT JOIN classroom cl ON s.building = cl.building AND s.room_number = cl.room_number LEFT JOIN takes myt ON myt.ID = #{id} AND myt.course_id = s.course_id AND myt.sec_id = s.sec_id AND myt.semester = s.semester AND myt.year = s.year WHERE s.semester = #{semester} AND s.year = #{year}
AND s.course_id = #{courseId}
ORDER BY s.course_id, s.sec_id

SELECT COUNT(*)
FROM section s
JOIN course c ON s.course_id = c.course_id
LEFT JOIN takes myt ON myt.ID = #{id}
    AND myt.course_id = s.course_id AND myt.sec_id = s.sec_id
    AND myt.semester = s.semester AND myt.year = s.year
WHERE s.semester = #{semester} AND s.year = #{year}

    AND s.course_id = #{courseId}

SELECT s.course_id, s.sec_id, s.semester, s.year, s.building, s.room_number, s.time_slot_id, c.title AS course_title, c.credits, (SELECT GROUP_CONCAT(i.name SEPARATOR '、') FROM teaches t JOIN instructor i ON t.ID = i.ID WHERE t.course_id = s.course_id AND t.sec_id = s.sec_id AND t.semester = s.semester AND t.year = s.year) AS instructor_names, (SELECT COUNT(*) FROM takes k WHERE k.course_id = s.course_id AND k.sec_id = s.sec_id AND k.semester = s.semester AND k.year = s.year) AS enrolled, cl.capacity, CASE WHEN myt.ID IS NOT NULL THEN 1 ELSE 0 END AS selected FROM section s JOIN course c ON s.course_id = c.course_id LEFT JOIN classroom cl ON s.building = cl.building AND s.room_number = cl.room_number LEFT JOIN takes myt ON myt.ID = #{id} AND myt.course_id = s.course_id AND myt.sec_id = s.sec_id AND myt.semester = s.semester AND myt.year = s.year WHERE s.semester = #{semester} AND s.year = #{year}
AND s.course_id = #{courseId}
ORDER BY s.course_id, s.sec_id LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM prereq p
LEFT JOIN takes t ON t.course_id = p.prereq_id AND t.ID = #{id}
    AND t.grade IS NOT NULL AND t.grade != 'F'
WHERE p.course_id = #{courseId}
  AND t.ID IS NULL

mapper.update:
UPDATE student
SET name = #{name}, dept_name = #{deptName}, tot_cred = #{totCred}
WHERE ID = #{id}
